from datetime import datetime, timezone

WALL_CLOCK = datetime(2026, 6, 18, 12, 0, 0, tzinfo=timezone.utc)
FRESHNESS_SLA_MIN = 15
VALID_STATUS = {"placed", "paid", "shipped", "cancelled"}
LAST_GOOD_REVENUE = 27549

EVENTS = [
    {"order_id": "o1", "amount_cents": 4999,  "created_at": "2026-06-18T11:38:00Z", "status": "paid"},
    {"order_id": "o2", "amount_cents": 12000, "created_at": "2026-06-18T11:31:00Z", "status": "placed"},
    {"order_id": "o3", "amount_cents": None,  "created_at": "2026-06-18T11:59:00Z", "status": "paid"},
    {"order_id": "o4", "amount_cents": 3050,  "created_at": "2026-06-18T11:40:00Z", "status": "shipped"},
    {"order_id": "o5", "amount_cents": 6200,  "created_at": "2026-06-18T11:20:00Z", "status": "refunded"},
]


def parse_ts(s):
    return datetime.fromisoformat(s.replace("Z", "+00:00"))


def age_min(ev):
    return (WALL_CLOCK - parse_ts(ev["created_at"])).total_seconds() / 60


def check_row(ev):
    amount = ev["amount_cents"]
    if not isinstance(amount, int) or amount <= 0:
        return (False, "amount_null_or_nonpositive")
    if ev["status"] not in VALID_STATUS:
        return (False, "schema_bad_status")
    return (True, "ok")


def check_freshness(candidates):
    # Feed freshness is a property of the BATCH, judged on the newest row that
    # actually passed the row gate. An empty candidate list is the dead-feed
    # case: absence is the loudest breach, never a vacuous pass.
    if not candidates:
        return (True, None, None)
    newest = min(candidates, key=age_min)
    a = age_min(newest)
    return (a > FRESHNESS_SLA_MIN, newest["order_id"], a)


def main():
    candidates = []
    quarantined = []

    for ev in EVENTS:
        ok, reason = check_row(ev)
        if ok:
            candidates.append(ev)
        else:
            quarantined.append((ev["order_id"], reason))

    stale, newest_id, newest_age = check_freshness(candidates)
    breach = bool(quarantined) or stale

    if breach:
        gross = LAST_GOOD_REVENUE
        served = "last_good"
    else:
        gross = sum(e["amount_cents"] for e in candidates)
        served = "fresh"

    print(f"row_gate: candidates={len(candidates)} quarantined={len(quarantined)}")
    for oid, reason in quarantined:
        print(f"quarantine {oid} {reason}")
    if newest_id is None:
        print(f"freshness: no candidates -> BREACH (feed presumed dead)")
    else:
        verdict = "BREACH" if stale else "OK"
        print(f"freshness: newest_candidate={newest_id} age={newest_age:.0f}min sla={FRESHNESS_SLA_MIN}min -> {verdict}")
    print(f"gate_breach={breach}")
    print(f"daily_gross_revenue={gross} ({served})")


main()

