        "amount_cents": "990",
        "receipt_email": "BOB@Test.io",
        "status": "failed",
        "created": "2024-01-11T14:05:00",
    },
    {
        "id": "ch_003",
        "customer": "cus_A",
        "amount_cents": "15000",
        "receipt_email": "Carol.M@Mail.NET",
        "status": "succeeded",
        "created": "2024-01-12T19:45:00",
    },
]


def stage_charge(raw):
    return {
        "charge_id": raw["id"],
        "customer_id": raw["customer"],
        "amount_cents": int(raw["amount_cents"]),
        "receipt_email": raw["receipt_email"].lower(),
        "charge_status": raw["status"],
        "created_at": raw["created"],
    }


def main():
    staged = [stage_charge(row) for row in RAW_CHARGES]
    for row in staged:
        print(
            f"{row['charge_id']}|{row['customer_id']}|{row['amount_cents']}|"
            f"{row['receipt_email']}|{row['charge_status']}|{row['created_at']}"
        )

    total = sum(row["amount_cents"] for row in staged)
    print(f"total_amount_cents={total}")


if __name__ == "__main__":
    main()

