RAW_ORDERS = [
    {"order_id": 1, "order_date": "2024-01-01", "amount": 100.0, "ingested_at": "2024-01-01T08:00:00"},
    {"order_id": 1, "order_date": "2024-01-01", "amount": 150.0, "ingested_at": "2024-01-01T10:00:00"},
    {"order_id": 2, "order_date": "2024-01-01", "amount": None,  "ingested_at": "2024-01-01T09:00:00"},
    {"order_id": 3, "order_date": "2024-01-02", "amount": 200.0, "ingested_at": "2024-01-02T07:00:00"},
    {"order_id": 4, "order_date": "2024-01-02", "amount": -50.0, "ingested_at": "2024-01-02T07:30:00"},
    {"order_id": 5, "order_date": "2024-01-02", "amount": 75.0,  "ingested_at": "2024-01-02T08:00:00"},
    {"order_id": 5, "order_date": "2024-01-02", "amount": 90.0,  "ingested_at": "2024-01-02T11:00:00"},
]


def build_stg_orders(raw):
    latest = {}
    for row in raw:
        oid = row["order_id"]
        if oid not in latest or row["ingested_at"] > latest[oid]["ingested_at"]:
            latest[oid] = row

    staging = []
    for oid in sorted(latest):
        row = latest[oid]
        amount = row["amount"] if row["amount"] is not None else 0
        if amount >= 0:
            staging.append({
                "order_id": oid,
                "order_date": row["order_date"],
                "amount": amount,
            })
    return staging


def build_mart_daily_revenue(stg):
    mart = {}
    for row in stg:
        day = row["order_date"]
        if day not in mart:
            mart[day] = {"daily_revenue": 0.0, "orders": 0}
        mart[day]["daily_revenue"] += row["amount"]
        mart[day]["orders"] += 1
    return mart


def main():
    stg = build_stg_orders(RAW_ORDERS)
    mart = build_mart_daily_revenue(stg)
    for order_date in sorted(mart):
        row = mart[order_date]
        print(f"{order_date} | revenue={row['daily_revenue']:.1f} | orders={row['orders']}")


if __name__ == "__main__":
    main()
